const file = $input.first().json;

const formatMap = { 'vtt': 'WebVTT', 'srt': 'SubRip', 'txt': 'Plain Text', 'json': 'Structured JSON' };
const format = file.format || file.filename.split('.').pop().toLowerCase();

// Build custom extractor instructions
const customExtractors = file.customExtractors || [];
let extractorInstructions = '';
if (customExtractors.length > 0) {
  extractorInstructions = '\n\n## Custom Extractors (REQUIRED - Add these sections)\n';
  customExtractors.forEach((e, i) => {
    extractorInstructions += `\n### ${i+1}. ${e.name}\n`;
    if (e.pattern) extractorInstructions += `- Pattern to match: ${e.pattern}\n`;
    if (e.instructions) extractorInstructions += `- Instructions: ${e.instructions}\n`;
    extractorInstructions += `- Output as a dedicated section in the summary\n`;
  });
}

return [{
  json: {
    ...file,
    format,
    formatName: formatMap[format] || 'Unknown',
    extractorInstructions,
    customExtractors,
    processingStarted: new Date().toISOString()
  }
}];

const input = $('Prepare Analysis').first().json;
const result = $json;

const isError = result.error || result.statusCode >= 400 || (result.result && result.result.includes('Error'));

if (isError) {
  return [{
    json: {
      success: false,
      filename: input.filename,
      format: input.format,
      error: result.error?.message || result.message || result.result || 'Unknown error',
      customExtractorsRun: input.customExtractors.map(e => e.name)
    }
  }];
}

const isComplete = (result.result || '').includes('COMPLETE');

return [{
  json: {
    success: isComplete,
    filename: input.filename,
    format: input.format,
    outputPath: input.outputPath,
    customExtractorsRun: input.customExtractors.map(e => e.name),
    completedAt: new Date().toISOString()
  }
}];
